    // By default, sort alphabetically if both helpfulness and verbosity are equal
    let comparison = a[0].localeCompare(b[0], undefined, { sensitivity: 'base' });
    if (aHelpfulness < bHelpfulness) {
      comparison *= -1;
    } else if (aHelpfulness > bHelpfulness) {
      comparison = 1;
    }

    return comparison;
  });

  return Object.fromEntries(entriesSorted);
}
