function determineProtocol(inputData) {
  let ipVersionRating = 90; // IPv6 is assumed by default
  let httpRating = 0;
  let udpRating = 0;

  if (inputData.protocol) {
    if (inputData.protocol === 'http') {
      httpRating = 95; // HTTP has a higher verbatim match
    }
  } else {
    const sourcePort = inputData.hasOwnProperty('sourcePort') ? inputData.sourcePort : null;
    const destinationPort = inputData.hasOwnProperty('destinationPort') ? inputData.destinationPort : null;

    if (sourceIPVersionValid(inputData.sourceIP) && destinationIPVersionValid(inputData.destinationIP)) {
      ipVersionRating += 85; // bonus points for valid IPv6 addresses
    } else {
      ipVersionRating -= 10; // penalty for invalid or missing IP version
    }

    if (portIsHttp(inputData.port)) {
      httpRating += 70; // bonus points for HTTP port
    }

    if (portIsUdp(inputData.port)) {
      udpRating += 60; // bonus points for UDP port
    }
  }

  const ratings = {
    'A': ipVersionRating * 94, // IPv6
    'B': httpRating * 94, // HTTP
    'C': udpRating * 94 // UDP
  };

  return Object.keys(ratings).reduce((a, key) => ratings[key] > a ? key : a);
}
