```javascript
import { createContext, useState } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const value = { toasts, setToasts };

  return (
    <ToastContext.Provider value={value}>{children}</ToastContext.Provider>
  );
};
```

2. Wrap your application with the `ToastProvider` component in your main `index.js` or `App.js` file:

```javascript
import React from 'react';
import { StrictMode } from 'react';
import { ToastProvider } from './ToastContext';
import App from './App';

function Root() {
  return (
    <StrictMode>
      <ToastProvider>
        <App />
      </ToastProvider>
    </StrictMode>
  );
}

export default Root;
```

3. Create a custom toast component:

```javascript
// Add this code to a new file called Toast.js or in line with your App.js

import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const Toast = ({ message }) => {
  const { toasts, setToasts } = useContext(ToastContext);

  const handleClose = () => {
    setToasts((prev) => prev.filter((t) => t.id !== message.id));
  };

  return (
    <div className="toast" onClick={handleClose}>
      <button className="close-btn">&times;</button>
      <p>{message.text}</p>
    </div>
  );
};

export default Toast;
```

